def sign(self, message: bytes) -> bytes:
    """Sign message under the loaded key's contract."""
    if isinstance(self.private_key, Ed25519PrivateKey):
        return self.private_key.sign(message)

    return self.private_key.sign(
        message,
        padding.PSS(
            mgf=padding.MGF1(hashes.SHA256()),
            salt_length=padding.PSS.DIGEST_LENGTH,
        ),
        hashes.SHA256(),
    )

def create_auth_headers(self, method: str, url: str) -> dict:
    current_time_milliseconds = int(time.time() * 1000)
    timestamp_str = str(current_time_milliseconds)

    if url.startswith("http"):
        from urllib.parse import urlparse

        path = urlparse(url).path
    else:
        path = url.split("?")[0]

    msg_string = timestamp_str + method.upper() + path
    message = msg_string.encode("utf-8")
    signature = self.sign(message)
    signature_b64 = base64.b64encode(signature).decode("utf-8")

    return {
        "KALSHI-ACCESS-KEY": self.key_id,
        "KALSHI-ACCESS-SIGNATURE": signature_b64,
        "KALSHI-ACCESS-TIMESTAMP": timestamp_str,
    }

