from decimal import Decimal
CENT = Decimal("0.01")
CENTICENT = Decimal("0.0001")

def d(s: str) -> Decimal:
    """*_dollars, fee_cost, balance_dollars, IndexedBalance.balance, SubaccountBalance.balance,
    GET intra-transfer 'amount'. Strings with up to 6 dp."""
    return Decimal(s)

def qty(s: str) -> Decimal:
    """*_fp counts: always 2 dp ('25.00'); position_fp is signed (+YES / -NO)."""
    return Decimal(s)

def from_cents(v: int) -> Decimal:
    """GetBalance.balance / portfolio_value, Settlement.revenue / value,
    Deposit/Withdrawal amount_cents / fee_cents, total_resting_order_value."""
    return Decimal(v) * CENT

def from_centicents(v: int) -> Decimal:
    """IncentiveProgram.period_reward / max_reward_per_account. 200000 -> 20.0000"""
    return Decimal(v) * CENTICENT

def to_centicents(usd: Decimal) -> int:
    """POST /portfolio/intra_exchange_instance_transfer 'amount' (integer centicents)."""
    return int((usd / CENTICENT).to_integral_exact())

def discount_factor(bps: int) -> Decimal:
    return Decimal(bps) / Decimal(10000)   # 5000 -> 0.5

