from decimal import Decimal, ROUND_FLOOR, ROUND_CEILING

TERMINAL_CODES = {10, 25}          # subscription is dead -> resubscribe

class SidSeq:
    """Detects gaps on sequenced channels (orderbook, trade, lifecycle, order_group_updates)."""
    def __init__(self):
        self.last = {}               # sid -> last seq seen

    def gap(self, frame: dict) -> bool:
        sid, seq = frame.get('sid'), frame.get('seq')
        if sid is None or seq is None:   # ticker/fill/user_order/market_position carry no seq
            return False
        prev = self.last.get(sid)
        self.last[sid] = seq
        return prev is not None and seq != prev + 1

def get_snapshot_cmd(cmd_id: int, sid: int, tickers: list) -> dict:
    # Only market_tickers is accepted for get_snapshot; it does not modify the subscription.
    # On a gap you cannot tell which market missed a delta, so pass every ticker on that sid.
    return {'id': cmd_id, 'cmd': 'update_subscription',
            'params': {'sids': [sid], 'market_tickers': tickers, 'action': 'get_snapshot'}}

def snap(price: Decimal, price_ranges: list, is_bid: bool) -> Decimal:
    """Snap a limit price onto the market grid (round bids down, asks up); off-grid prices are rejected."""
    for band in price_ranges:
        start, end, step = (Decimal(band[k]) for k in ('start', 'end', 'step'))
        if start <= price <= end:
            n = ((price - start) / step).to_integral_value(ROUND_FLOOR if is_bid else ROUND_CEILING)
            return start + n * step
    raise ValueError('price outside price_ranges')

